INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein aktiver Messfühler immer Hilfsenergie benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Aktive Messfühler erzeugen eigenes Signal"}, {"text": "Ja", "correct": false, "because": "Passive benötigen Hilfsenergie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip nutzt ein Thermoelement zur Messung?', 3, '[{"text": "Thermoelektrischer Effekt", "correct": true, "because": "Erzeugt Spannung durch Temperaturunterschied"}, {"text": "Piezoelektrischer Effekt", "correct": false, "because": "Für Drucksensoren"}, {"text": "Photoelektrischer Effekt", "correct": false, "because": "Für Lichtsensoren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Messgrößen kann ein typisches Bauteil erfassen?', 5, '[{"text": "Temperatur", "correct": true, "because": "Häufige Messgröße"}, {"text": "Druck", "correct": true, "because": "Physikalische Größe"}, {"text": "Feuchtigkeit", "correct": true, "because": "Umgebungsbedingung"}, {"text": "Farbe", "correct": false, "because": "Keine physikalische Messgröße"}, {"text": "Gewicht", "correct": false, "because": "Nicht direkt gemessen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Passive Messfühler benötigen Hilfsenergie. b) Sie erzeugen eigene Signale.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, aktive erzeugen Signale"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Messfühlers?', 4, '[{"text": "Messbereich", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Genauigkeit", "correct": false, "because": "Beeinflusst Ergebnisse"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein kapazitiver Fühler auch nicht-metallische Objekte erkennt?', 2, '[{"text": "Ja", "correct": true, "because": "Erkennt Veränderung der Kapazität"}, {"text": "Nein", "correct": false, "because": "Nicht auf Metall beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Bauteil misst Abstände berührungslos?', 4, '[{"text": "Ultraschallsensor", "correct": true, "because": "Nutzt Schallwellen"}, {"text": "Thermistorsensor", "correct": false, "because": "Für Temperatur"}, {"text": "PTC-Widerstand", "correct": false, "because": "Für Temperatur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass piezoelektrische Fühler nur dynamische Größen messen. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Erzeugen Signal bei Änderung"}, {"text": "Nein", "correct": false, "because": "Statische Messung nicht möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Lichtsensor ein aktiver Messfühler?', 2, '[{"text": "Ja", "correct": true, "because": "Nutzt photoelektrischen Effekt"}, {"text": "Nein", "correct": false, "because": "Erzeugt eigenes Signal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl eines Messfühlers?', 5, '[{"text": "Messgenauigkeit", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Umgebungsbedingungen", "correct": true, "because": "Beeinflussen Funktion"}, {"text": "Verpackungsdesign", "correct": false, "because": "Kosmetisch"}, {"text": "Gerätegröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Fühlers für hohe Temperaturen?', 4, '[{"text": "Temperaturbeständigkeit", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnelle Reaktion", "correct": false, "because": "Sekundär"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Induktive Fühler erkennen nur Metall. b) Sie benötigen Hilfsenergie.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Metall detektiert, b) passive Technik"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Auswahl eines Messfühlers?', 3, '[{"text": "Wirkprinzip", "correct": false, "because": "Bestimmt Funktion"}, {"text": "Messbereich", "correct": false, "because": "Definiert Einsatz"}, {"text": "Markenlogo", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich einen Fühler für Feuchtigkeit auswähle?', 4, '[{"text": "Messbereich und Genauigkeit prüfen", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Nur Größe prüfen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Prüfung wählen", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass alle Messfühler digitale Signale liefern. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Viele liefern analoge Signale"}, {"text": "Ja", "correct": false, "because": "Analoge Signale üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip nutzt ein optischer Messfühler?', 4, '[{"text": "Lichtreflexion", "correct": true, "because": "Erkennt Abstand oder Objekte"}, {"text": "Wärmeleitung", "correct": false, "because": "Für Temperatur"}, {"text": "Druckänderung", "correct": false, "because": "Für Drucksensoren"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Messfühler auch als Aktor dienen?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Piezoelemente"}, {"text": "Nein", "correct": false, "because": "Umkehrprinzip möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben passive Messfühler?', 5, '[{"text": "Hilfsenergie nötig", "correct": true, "because": "Externe Stromquelle"}, {"text": "Komplexere Schaltung", "correct": true, "because": "Signalumwandlung nötig"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Nachteil"}, {"text": "Einfache Wartung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Fühlers unwichtig?', 3, '[{"text": "Umgebungsbedingungen", "correct": false, "because": "Beeinflussen Funktion"}, {"text": "Signalart", "correct": false, "because": "Bestimmt Verarbeitung"}, {"text": "Gehäusedekor", "correct": true, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich einen Messfühler für eine Industrieanlage auswähle?', 4, '[{"text": "Anwendung, Umgebung und Genauigkeit prüfen", "correct": true, "because": "Sichert Eignung"}, {"text": "Nur Preis prüfen", "correct": false, "because": "Ignoriert Funktion"}, {"text": "Ohne Analyse wählen", "correct": false, "because": "Riskiert Fehlfunktion"}]');
